def queue_gate(name, qi, now):
    """队列 qi 在 now 的暂停截止：全局 PAUSE 与有效 PFC 最大值。

    有效 PFC 截止仅计入映射到 qi 且在该口 pfc 允许集合内的优先级；
    已到期（<= now）的截止视为 None。
    """
    gate = pause_until[name]
    if gate is not None and gate <= now:
        gate = None
    allowed = pfc_allowed[name]
    for prio in queue_prios[qi]:
        if prio not in allowed:
            continue
        until = pfc_until[name][prio]
        if until is not None and until > now and (
            gate is None or until > gate
        ):
            gate = until
    return gate

def pfc_decider(name, prio, g_until):
    """prio 是否为其队列门控的决定者：允许、存活，且截止严格大于全局
    PAUSE 并为同队列允许优先级中的最大者（并列取编号最小者）。"""
    until = pfc_until[name][prio]
    if until is None or prio not in pfc_allowed[name]:
        return False
    if g_until is not None and until <= g_until:
        return False
    qi = qos_map[prio]
    for other in queue_prios[qi]:
        if other == prio or other not in pfc_allowed[name]:
            continue
        ountil = pfc_until[name][other]
        if ountil is not None and ountil > until:
            return False
    return True

def pfc_deciders(name, g_until):
