    """门控状态在 t 变更后重设活动区间起点。

    延续决定身份的优先级自 t 续计；新成为决定者的优先级自 base（在发帧
    完成时刻或 t）起计——在发帧不被 PFC 抢占，其占用时段不算阻塞；失去
    决定身份者起点清空。
    """
    g_until = pause_until[name]
    for prio in range(8):
        until = pfc_until[name][prio]
        if until is None or not pfc_decider(name, prio, g_until):
            pfc_began[name][prio] = None
        elif prio in prev:
            pfc_began[name][prio] = t if until > t else None
        else:
            pfc_began[name][prio] = base if until > base else None

def sync_change(name, t, prev, base):
    """门控状态在 t 变更后重设活动区间起点。

    延续决定身份的优先级自 t 续计；新成为决定者的优先级自 base（在发帧
    完成时刻或 t）起计——在发帧不被 PFC 抢占，其占用时段不算阻塞；失去
    决定身份者起点清空。
