    g_until = pause_until[name]
    for prio in range(8):
        until = pfc_until[name][prio]
        if until is None or not pfc_decider(name, prio, g_until):
            pfc_began[name][prio] = None
        elif prio in prev:
            pfc_began[name][prio] = t if until > t else None
        else:
            pfc_began[name][prio] = base if until > base else None

def accrue_holds(name, now):
    """结算全局 PAUSE 与各优先级 PFC 到 now 的实际阻塞区间。

    窗口内可能发生全局 PAUSE 与多个 PFC 截止到期：按到期时刻依次处理，
    时刻 τ 前先把在计时区间累计到 τ，移除该时刻到期截止后重判门控
    决定者（全局 PAUSE 到期可让更长的 PFC 接管，反之被覆盖的 PFC 到期
    不计时）。PFC 仅在其为队列门控决定者的时段计入对应优先级。
    """
    began = hold_began[name]
    until = pause_until[name]
    g_expire = None
    if until is not None and now >= until:
        if began is not None and until > began:
            pause_ns[name] += until - began
        hold_began[name] = None
        pause_until[name] = None
        g_expire = until
    elif until is not None and began is not None and now > began:
        pause_ns[name] += now - began
        hold_began[name] = now
    # PFC 时间线：合并本窗口内的全局到期点与各优先级到期点
    instants = sorted({
        u for u in pfc_until[name] if u is not None and u <= now
    } | ({g_expire} if g_expire is not None else set()))
    for tau in instants:
        for prio in range(8):  # 先关闭在计时区间到 τ
            pb = pfc_began[name][prio]
            if pb is not None and tau > pb:
                pfc_ns[name][prio] += tau - pb
        if tau == g_expire:
            pause_until[name] = None
            hold_began[name] = None
        for prio in range(8):  # 移除 τ 到期的 PFC 截止
            if pfc_until[name][prio] == tau:
                pfc_until[name][prio] = None
                pfc_began[name][prio] = None
        g_until = pause_until[name]  # 可能已在本时刻到期清除
        for prio in range(8):
            if pfc_until[name][prio] is None:
                pfc_began[name][prio] = None
            elif pfc_decider(name, prio, g_until):
                # 接管决定身份：自 τ 起计时（原在计者亦在 τ 续计）
                pfc_began[name][prio] = tau
            else:
                pfc_began[name][prio] = None
    # 仍存活的决定者区间累计到 now
    for prio in range(8):
        pb = pfc_began[name][prio]
        if pb is not None and now > pb:
            pfc_ns[name][prio] += now - pb
            pfc_began[name][prio] = now

def settle_negotiations(t):
    settled = 0
    for port in fwd_ports:
        name = port["name"]
        if name in pending and pending[name][2] <= t:
            rate, mode, _ = pending.pop(name)
            committed[name] = ("up", rate, mode)
            settled += 1
    return settled

